	status = "okay";

	ports {
		port {
			dsi0_out: endpoint {
				remote-endpoint = <&lt9611_in>;
			};
		};
	};
};

/* 2) 桥本体 */
&i2c4 {
	lt9611_codec: hdmi-bridge@3b {
		compatible = "lontium,lt9611";
		reg = <0x3b>;
		#sound-dai-cells = <1>;

		interrupt-parent = <&pio>;
		interrupts = <68 IRQ_TYPE_LEVEL_LOW>;
		reset-gpios = <&pio 69 GPIO_ACTIVE_LOW>;

		vdd-supply = <&lt9611_1v8>;
